        first, last = "k,m,v\na,1,p\nb,1,q\na,2,s\n", "k,m,v\na,1,r\na,2,s\nb,1,t\n"
        for argv, want in [(["dedupe", "d.csv", "k", "m"], first), (["--keep", "first", "dedupe", "d.csv", "k", "m"], first),
                           (["--keep=first", "dedupe", "d.csv", "k", "m"], first), (["--keep", "last", "dedupe", "d.csv", "k", "m"], last),
                           (["--keep=last", "dedupe", "d.csv", "k", "m"], last), (["dedupe", "d.csv", "k", "m", "--keep", "last"], last),
                           (["dedupe", "--keep=last", "d.csv", "k", "m"], last), (["dedupe", "d.csv", "k", "m", "--keep=last", "--keep=first"], first),
                           (["dedupe", "d.csv", "k"], "k,m,v\na,1,p\nb,1,q\n"), (["--keep=last", "dedupe", "d.csv", "k"], "k,m,v\na,2,s\nb,1,t\n"),
                           (["--keep=last", "dedupe", "d.csv", "m", "k"], last), (["dedupe", "d.csv", "k", "k"], "k,m,v\na,1,p\nb,1,q\n")]:
            self.ok(["--format=csv"] + argv, want)

    def test_text_equality_and_no_duplicates(self):
        f = {"d.csv": "k\n1\n1.0\n 1\n1 \nA\na\n1\n"}
        self.ok(["--format=csv", "dedupe", "d.csv", "k"], "k\n1\n1.0\n 1\n1 \nA\na\n", f)
        self.ok(["--format=csv", "--keep=last", "dedupe", "d.csv", "k"], "k\n1.0\n 1\n1 \nA\na\n1\n", f)
        self.ok(["--format=csv", "dedupe", "d.csv", "m", "v"], "k,m,v\na,1,p\nb,1,q\na,1,r\na,2,s\nb,1,t\n")

    def test_options_accepted_on_show_and_bad_values(self):
        self.ok(["--keep", "last", "--kind=left", "show", "d.csv", "--keep=first"], "k  m  v\na  1  p\nb  1  q\na  1  r\na  2  s\nb  1  t\n")
        for argv in (["--keep", "middle", "dedupe", "d.csv", "k"], ["dedupe", "d.csv", "k", "--keep="], ["dedupe", "d.csv", "k", "--keep"],
                     ["--keep=LAST", "dedupe", "d.csv", "k"], ["--keep", "inner", "show", "d.csv"]):
            self.bad(argv, 2)

    def test_mistakes(self):
        self.bad(["dedupe", "d.csv", "nope"], 1, "d.csv: no column 'nope' (columns: k, m, v)")
        self.bad(["dedupe", "d.csv", "k", "nope"], 1, "d.csv: no column 'nope' (columns: k, m, v)")
        self.bad(["dedupe", "missing.csv", "k"], 1)

    def test_usage_errors(self):
        for argv in (["dedupe"], ["dedupe", "d.csv"], ["dedupe", "missing.csv"]):
            self.bad(argv, 2)


if __name__ == "__main__":
    unittest.main()
