    def test_values(self):
        for values, row in [(("1", "2", "4"), "3,1,4,2.33,2.00"), (("7",), "1,7,7,7.00,7.00"), (("2.345",), "1,2.345,2.345,2.35,2.35"),
                            (("-2.345",), "1,-2.345,-2.345,-2.35,-2.35"), (("10.50", "9"), "2,9,10.50,9.75,9.75"), (("0.004", "0.005"), "2,0.004,0.005,0.00,0.00"),
                            (("1", "2", "2", "10"), "4,1,10,3.75,2.00"), (("-0", "0"), "2,0,0,0.00,0.00"), ((" 5 ", "5.0"), "2,5.0,5,5.00,5.00".replace("5.0,5", "5,5.0"))]:
            with self.subTest(values):
                self.ok(["--format=csv", "stats", "t.csv", "v"], HEAD + "v,%s\n" % row, {"t.csv": "v\n" + "".join("%s\n" % v for v in values)})

    def test_no_numbers(self):
        f = {"t.csv": "k,m\n,1\n ,2\n"}
        self.ok(["--format=csv", "stats", "t.csv", "k"], HEAD + "k,0,,,,\n", f)
        self.ok(["stats", "t.csv", "k"], "column  count  min  max  mean  median\nk       0\n", f)
        self.ok(["--format=json", "stats", "t.csv", "k", "m"], '[{"column": "k", "count": "0", "min": "", "max": "", "mean": "", "median": ""}, '
                '{"column": "m", "count": "2", "min": "1", "max": "2", "mean": "1.50", "median": "1.50"}]\n', f)
        self.ok(["--format=csv", "stats", "t.csv", "k"], HEAD + "k,0,,,,\n", {"t.csv": "k\n"})

    def test_exact_big_numbers(self):
        big = "1" + "0" * 80
        self.ok(["--format=csv", "stats", "t.csv", "v"], HEAD + "v,2,1,%s,%s.50,%s.50\n" % (big, "5" + "0" * 79, "5" + "0" * 79),
                {"t.csv": "v\n%s\n1\n" % big})

    def test_mistakes(self):
        self.bad(["stats", "s.csv", "a", "b"], 1, "s.csv: row 1: column 'b': 'x' is not a number")
        self.bad(["stats", "s.csv", "nope"], 1, "s.csv: no column 'nope' (columns: a, b, c)")
        self.bad(["stats", "s.csv", "b", "nope"], 1, "s.csv: no column 'nope' (columns: a, b, c)")
        self.bad(["stats", "t.csv", "v"], 1, "t.csv: row 2: column 'v': '1e3' is not a number", {"t.csv": "v\n1\n1e3\n"})
        self.bad(["stats", "missing.csv", "a"], 1)

    def test_usage_errors(self):
        for argv in (["stats"], ["stats", "s.csv"], ["stats", "missing.csv"]):
            self.bad(argv, 2)


if __name__ == "__main__":
    unittest.main()
